def choose_move(observation):
    def getv(obj, key, default=None):
        if hasattr(obj, "get"):
            try:
                return obj.get(key, default)
            except Exception:
                return default
        return default

    def clamp_step(v):
        try:
            v = int(v)
        except Exception:
            return 0
        if v > 1:
            return 1
        if v < -1:
            return -1
        return v

    def pos(val, default=(0, 0)):
        if isinstance(val, (list, tuple)) and len(val) >= 2:
            try:
                return int(val[0]), int(val[1])
            except Exception:
                return default
        return default

    def step_toward(src, dst):
        sx, sy = src
        tx, ty = dst
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def dist(a, b):
        ax, ay = a
        bx, by = b
        return abs(ax - bx) + abs(ay - by)

    def norm_points(val):
        out = []
        if isinstance(val, (list, tuple)):
            for item in val:
