                best_score = score
                target = c
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = norm_points(getv(observation, "unclaimed_cells", None))
        if not targets:
            targets = norm_points(getv(observation, "opponent_territory", None))
        if not targets:
            targets = norm_points(getv(observation, "neutral_cells", None))
        if not targets:
            targets = norm_points(getv(observation, "frontier_cells", None))
