                if d < best_d:
                    best_d = d
                    best = t
            return step_toward(self_pos, best)
        return step_toward(self_pos, opp_pos)

    resources = norm_points(getv(observation, "resources", None))
    if not resources:
        resources = norm_points(getv(observation, "resource_positions", None))
    if not resources:
